import requests
from requests.models import RequestEncodingMixin

class FileWrapper:
    def __init__(self, content):
        self._content = content
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=None: self._content
        raise AttributeError(name)

def test_getattr_read():
    files = {'file': FileWrapper(b'hello world')}
    # We need to call _encode_files. It's a static method of RequestEncodingMixin (or its subclasses)
